import collections
import os
import glob
import pandas as pd

def task_func(my_tuple, path_csv_files):
    """
    Count occurrences of each value in the specified columns across multiple CSV files.

    Parameters
    ----------
    my_tuple : tuple, list, set, or str
        Column name(s) to count.
    path_csv_files : str or iterable
        A path to a CSV file, a directory containing CSV files, or an iterable of CSV file paths.

    Returns
    -------
    dict
        A dictionary where keys are column names and values are dictionaries
        mapping unique values in the column to their counts.
    """
    if my_tuple is None:
        columns = []
    elif isinstance(my_tuple, (list, tuple, set)):
        columns = list(my_tuple)
    else:
        columns = [my_tuple]

    # Resolve the list of CSV files.
    if isinstance(path_csv_files, str):
        if os.path.isdir(path_csv_files):
            files = sorted(glob.glob(os.path.join(path_csv_files, "*.csv")))
        else:
            files = [path_csv_files]
    else:
        try:
            files = list(path_csv_files)
        except TypeError:
            files = [path_csv_files]

    counters = {col: collections.Counter() for col in columns}

    for file_path in files:
        if not file_path:
            continue
        try:
            df = pd.read_csv(file_path)
        except Exception:
            continue

        for col in columns:
            if col not in df.columns:
                continue

            counts = df[col].value_counts(dropna=False)
            for value, count in counts.items():
                if pd.isna(value):
                    key = None
                elif hasattr(value, "item"):
                    try:
                        key = value.item()
                    except Exception:
                        key = value
                else:
                    key = value
                counters[col][key] += int(count)

    return {col: dict(counter) for col, counter in counters.items()}
